function renderLastExport(){if(!$('lastExport'))return;if(!lastExport){$('lastExport').replaceChildren();return;}$('lastExport').innerHTML=`<div class="export-result"><strong>✓ Tệp xuất đã sẵn sàng</strong><span>${esc(lastExport.name)}</span><small>${lastExport.width} × ${lastExport.height} · ${lastExport.duration.toFixed(1)}s · ${(lastExport.size/1024/1024).toFixed(2)} MB</small><button id="downloadLast">${icon('download')}Tải lại tệp</button></div>`;$('downloadLast').onclick=()=>download(lastExport.url,lastExport.name);}
$('cancelExport').onclick=()=>{exportCancelled=true;$('cancelExport').disabled=true;$('exportMessage').textContent='Đang dừng và dọn bộ mã hóa…';};$('exportDialog').addEventListener('cancel',e=>{e.preventDefault();exportCancelled=true;});
$('mainNav').onclick=e=>{const b=e.target.closest('[data-view]');if(b)setView(b.dataset.view);};document.querySelector('.brand').onclick=e=>{e.preventDefault();setView('production');};document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());$('poolDialog').addEventListener('close',()=>{save();render();});$('themeToggle').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';save();document.documentElement.dataset.theme=state.theme;if(view==='editor')paintWave(waveBuffer);};$('helpOpen').onclick=()=>modal('helpDialog');$('demoReset').onclick=()=>{if(exporting)return;stopPreview();for(const j of state.jobs)engine.stop(j.id);seedJobs();setView('production');notify('Đã tạo lại 13 sản phẩm mẫu. Media bạn tải lên vẫn được giữ.');};$('productFiles').onchange=safe(async e=>{await importFiles([...e.target.files],true);e.target.value='';});$('libraryFiles').onchange=safe(async e=>{await importFiles([...e.target.files],false);e.target.value='';});$('importGrouping').onclick=e=>{const b=e.target.closest('[data-group]');if(b){grouping=b.dataset.group;document.querySelectorAll('[data-group]').forEach(b=>b.classList.toggle('active',b.dataset.group===grouping));}};wireDrop($('productDrop'),files=>importFiles(files,true));$('productFromLibrary').onclick=()=>openPicker('image',a=>{addJob([a],a.name.replace(/\.[^.]+$/,''));$('productDialog').close();setView('production');},'Chọn ảnh làm sản phẩm mới');$('renameForm').onsubmit=safe(async e=>{e.preventDefault();const a=asset(renameId),name=$('renameValue').value.trim();if(!a||!name)throw Error('Nhập tên media.');a.name=name;if(!a.demo)await storeAsset(a);$('renameDialog').close();renderLibrary();notify('Đã đổi tên media.');});
window.addEventListener('resize',()=>{if(view==='editor'){paintWave(waveBuffer);updateTrims();}else if(view==='production'&&state.compactQueue==null&&document.querySelector('#main .page')?.classList.contains('compact-batch')!==(innerHeight<850))renderProduction();});window.addEventListener('beforeunload',e=>{saveNow();if(exporting){e.preventDefault();e.returnValue='';}});let lastTick=performance.now();setInterval(()=>{const now=performance.now();engine.tick(now-lastTick);lastTick=now;updateProduction();},120);void init().catch(error=>{notify('Chưa mở được bản xem trước: '+error.message,true);console.error(error);});
